"""codebench_mpl2plotly — showcase REAL matplotlib figures through plotly.

The full C matplotlib stays the computation/rendering engine (savefig, exact
API); this module converts a drawn Figure into a plotly Figure for DISPLAY so
the preview gets plotly's interaction: hover tooltips with data values,
smooth wheel/pinch zoom, drag pan, legend toggling, and orbitable 3-D.

Strategy
────────
* plotly's bundled `mpl_to_plotly` (matplotlylib) converts the artists it
  understands: Line2D, scatter/PathCollection, bars, subplots, log axes,
  date axes, titles/labels.
* Artists whose source data CANNOT be recovered from the artist tree
  (contourf grids, pie fractions, 3-D surfaces) are handled by
  **capture-at-call**: `install_capture()` wraps the plotting methods to
  stash the original arrays on the returned artist, and `convert()` emits
  exact plotly traces (go.Contour / go.Pie / go.Surface) from them.
* Artists matplotlylib silently drops are supplemented here:
  imshow→Heatmap, pcolormesh→Heatmap, fill_between→filled Scatter.

`convert(fig)` returns `(plotly_figure | None, notes)`. None means "not
faithfully convertible" — the caller falls back (SVG viewer / WebAgg / PNG).
"""
import warnings

_NOTES_LIMIT = 12


# ────────────────────────── capture-at-call ──────────────────────────
def install_capture():
    """Wrap data-lossy plotting methods so the original arrays ride along
    on the artist. Idempotent; call once at pyplot-import time."""
    try:
        from matplotlib.axes import Axes
    except Exception:
        return

    def _wrap(cls, name, stash):
        orig = getattr(cls, name, None)
        if orig is None or getattr(orig, "_cb_capture", False):
            return
        def wrapped(self, *a, **k):
            art = orig(self, *a, **k)
            try:
                stash(self, art, a, k)
            except Exception:
                pass
            return art
        wrapped._cb_capture = True
        wrapped.__name__ = name
        setattr(cls, name, wrapped)

    def _grid_stash(kind):
        def stash(ax, art, a, k):
            # accepted signatures: (Z), (X, Y, Z), (Z, levels), (X, Y, Z, levels)
            arrs = [x for x in a if hasattr(x, "ndim")]
            if len(arrs) >= 3:
                X, Y, Z = arrs[0], arrs[1], arrs[2]
            elif len(arrs) >= 1:
                X = Y = None; Z = arrs[0]
            else:
                return
            art._cb_grid = (kind, X, Y, Z)
        return stash

    _wrap(Axes, "contourf", _grid_stash("contourf"))
    _wrap(Axes, "contour",  _grid_stash("contour"))

    def _pie_stash(ax, art, a, k):
        vals = a[0] if a else k.get("x")
        labels = k.get("labels")
        if len(a) > 1 and labels is None:
            labels = a[1]
        if vals is None:
            return
        ax._cb_pie = (list(vals), list(labels) if labels is not None else None)
    _wrap(Axes, "pie", _pie_stash)

    try:
        from mpl_toolkits.mplot3d.axes3d import Axes3D

        def _surf_stash(ax, art, a, k):
            arrs = [x for x in a if hasattr(x, "ndim")]
            if len(arrs) >= 3:
                art._cb_surface = (arrs[0], arrs[1], arrs[2],
                                   k.get("cmap"), k.get("color"))
        _wrap(Axes3D, "plot_surface",   _surf_stash)
        _wrap(Axes3D, "plot_wireframe", _surf_stash)
    except Exception:
        pass


# ─────────────────────────── helpers ────────────────────────────────
def _cmap_to_colorscale(cmap, n=16):
    import matplotlib.cm as cm
    import matplotlib.colors as mcolors
    try:
        cmap = cm.get_cmap(cmap) if isinstance(cmap, (str, type(None))) else cmap
    except Exception:
        from matplotlib import colormaps
        cmap = colormaps.get_cmap(cmap or "viridis")
    out = []
    for i in range(n):
        t = i / (n - 1)
        r, g, b, _ = cmap(t)
        out.append([round(t, 4), f"rgb({int(r*255)},{int(g*255)},{int(b*255)})"])
    return out


def _css(color, alpha=None):
    import matplotlib.colors as mcolors
    try:
        r, g, b, a = mcolors.to_rgba(color, alpha)
        return f"rgba({int(r*255)},{int(g*255)},{int(b*255)},{round(a,3)})"
    except Exception:
        return None


def _tolist(x):
    return x.tolist() if hasattr(x, "tolist") else list(x)


# ─────────────────────────── 3-D branch ─────────────────────────────
def _convert_3d(fig, notes):
    import numpy as np
    import plotly.graph_objects as go
    traces = []
    scene_title = None
    labels = {}
    for ax in fig.axes:
        if getattr(ax, "name", "") != "3d":
            continue
        scene_title = scene_title or (ax.get_title() or None)
        labels = {"x": ax.get_xlabel() or "x",
                  "y": ax.get_ylabel() or "y",
                  "z": ax.get_zlabel() or "z"}
        # surfaces / wireframes captured at call time
        for coll in list(ax.collections):
            surf = getattr(coll, "_cb_surface", None)
            if surf is not None:
                X, Y, Z, cmap, color = surf
                cs = _cmap_to_colorscale(cmap) if (cmap or color is None) else None
                kw = dict(x=np.asarray(X), y=np.asarray(Y), z=np.asarray(Z),
                          showscale=False)
                if cs: kw["colorscale"] = cs
                if color and not cmap:
                    c = _css(color)
                    if c: kw["colorscale"] = [[0, c], [1, c]]
                traces.append(go.Surface(**kw))
                continue
            # 3-D scatter
            off3 = getattr(coll, "_offsets3d", None)
            if off3 is not None:
                xs, ys, zs = (np.asarray(v, float) for v in off3)
                try:
                    fc = coll.get_facecolor()
                    col = _css(fc[0]) if len(fc) else None
                except Exception:
                    col = None
                try:
                    sz = float(np.sqrt(max(coll.get_sizes().mean(), 1.0)))
                except Exception:
                    sz = 5.0
                traces.append(go.Scatter3d(
                    x=xs, y=ys, z=zs, mode="markers",
                    marker=dict(size=max(2.5, min(sz, 14)), color=col),
                    name=str(getattr(coll, "get_label", lambda: "")()) or None))
                continue
            notes.append(f"3d: unconverted collection {type(coll).__name__}")
        for ln in ax.lines:                       # Line3D
            try:
                xs, ys, zs = ln.get_data_3d()
                traces.append(go.Scatter3d(
                    x=_tolist(xs), y=_tolist(ys), z=_tolist(zs), mode="lines",
                    line=dict(color=_css(ln.get_color()), width=max(2, ln.get_linewidth()*2)),
                    name=(ln.get_label() if not str(ln.get_label()).startswith("_") else None)))
            except Exception as e:
                notes.append(f"3d line: {e}")
    if not traces:
        return None

    # iOS WebKit (the app's WKWebView) cannot render plotly's WebGL glyph
    # atlas — every gl-text string (3-D tick labels, axis titles) comes out
    # as tofu boxes, even though the SAME file renders fine in macOS Safari.
    # So: strip ALL WebGL text from the scene and put the information in the
    # SVG/HTML layer instead, which renders crisply here:
    #   • rich hovertemplate → exact x/y/z values on touch/hover
    #   • title + a ranges line ("x: label [min…max] · …") as SVG text
    #   • grid/zero lines stay (pure geometry, no text)
    import numpy as np

    def _rng(vals):
        try:
            arr = np.asarray(vals, float)
            lo, hi = float(np.nanmin(arr)), float(np.nanmax(arr))
            return f"{lo:.4g} … {hi:.4g}"
        except Exception:
            return "—"

    xs_all, ys_all, zs_all = [], [], []
    for t in traces:
        for src, dst in (("x", xs_all), ("y", ys_all), ("z", zs_all)):
            v = getattr(t, src, None)
            if v is not None:
                try: dst.append(np.asarray(v, float).ravel())
                except Exception: pass
        try:
            t.update(hovertemplate=(
                f"{labels.get('x','x')}: %{{x:.5g}}<br>"
                f"{labels.get('y','y')}: %{{y:.5g}}<br>"
                f"{labels.get('z','z')}: %{{z:.5g}}<extra></extra>"))
        except Exception:
            pass

    def _cat(parts):
        try: return np.concatenate(parts) if parts else None
        except Exception: return None

    ranges = " · ".join(
        f"{labels.get(k, k)}: [{_rng(v)}]"
        for k, v in (("x", _cat(xs_all)), ("y", _cat(ys_all)), ("z", _cat(zs_all)))
        if v is not None)

    pf = go.Figure(data=traces)
    # Even an EMPTY title string creates a gl-text node that the broken
    # atlas draws as one tofu box per axis — shrink it to a sub-pixel font
    # so nothing visible remains while grid geometry stays.
    ax_no_text = dict(showticklabels=False,
                      title=dict(text="", font=dict(size=1)))
    pf.update_layout(
        title=dict(text=scene_title or "", x=0.5, xanchor="center"),
        scene=dict(xaxis=ax_no_text, yaxis=ax_no_text, zaxis=ax_no_text),
        margin=dict(l=0, r=0, t=48 if scene_title else 30, b=44),
        template="plotly_white",
        annotations=[dict(
            text=ranges, showarrow=False, xref="paper", yref="paper",
            x=0.5, y=-0.02, xanchor="center", yanchor="top",
            font=dict(size=11, color="#666"))] if ranges else [])
    return pf


# ─────────────────────────── 2-D branch ─────────────────────────────
def _supplement_2d(fig, pf, notes):
    """Add traces matplotlylib dropped: images, quadmesh, fill_between,
    captured contour(f) grids, captured pies."""
    import numpy as np
    import plotly.graph_objects as go
    from matplotlib.collections import PolyCollection, QuadMesh
    added = 0
    for ax in fig.axes:
        for im in getattr(ax, "images", []):          # imshow → Heatmap
            try:
                A = np.asarray(im.get_array())
                if A.ndim == 3:                        # RGB(A) → go.Image
                    pf.add_trace(go.Image(z=(A[..., :3] * 255).astype("uint8")
                                          if A.dtype.kind == "f" else A[..., :3]))
                    added += 1
                    continue
                x0, x1, y0, y1 = im.get_extent()
                origin_upper = im.origin == "upper"
                z = A[::-1] if origin_upper else A
                pf.add_trace(go.Heatmap(
                    z=z, colorscale=_cmap_to_colorscale(im.get_cmap()),
                    x0=min(x0, x1), dx=abs(x1 - x0) / max(A.shape[1], 1),
                    y0=min(y0, y1), dy=abs(y1 - y0) / max(A.shape[0], 1),
                    showscale=bool(getattr(im, "colorbar", None))))
                added += 1
            except Exception as e:
                notes.append(f"imshow: {e}")
        for coll in ax.collections:
            grid = getattr(coll, "_cb_grid", None)
            if grid is not None:                       # captured contour(f)
                try:
                    kind, X, Y, Z = grid
                    kw = dict(z=np.asarray(Z),
                              colorscale=_cmap_to_colorscale(getattr(coll, "get_cmap", lambda: None)()),
                              contours=dict(coloring="fill" if kind == "contourf" else "lines"),
                              showscale=bool(getattr(coll, "colorbar", None)),
                              line_width=1 if kind == "contour" else 0.3)
                    if X is not None and getattr(X, "ndim", 1) >= 1:
                        Xa, Ya = np.asarray(X), np.asarray(Y)
                        kw["x"] = Xa[0] if Xa.ndim == 2 else Xa
                        kw["y"] = Ya[:, 0] if Ya.ndim == 2 else Ya
                    lv = getattr(coll, "levels", None)
                    if lv is not None and len(lv) > 1:
                        kw["contours"].update(start=float(lv[0]), end=float(lv[-1]),
                                              size=float(lv[1] - lv[0]))
                    pf.add_trace(go.Contour(**kw))
                    added += 1
                    continue
                except Exception as e:
                    notes.append(f"contour: {e}")
            if isinstance(coll, QuadMesh):             # pcolormesh
                try:
                    A = np.asarray(coll.get_array())
                    coords = np.asarray(coll._coordinates)
                    if A.ndim == 1:
                        A = A.reshape(coords.shape[0] - 1, coords.shape[1] - 1)
                    pf.add_trace(go.Heatmap(
                        z=A, x=coords[0, :, 0], y=coords[:, 0, 1],
                        colorscale=_cmap_to_colorscale(coll.get_cmap()),
                        showscale=bool(getattr(coll, "colorbar", None))))
                    added += 1
                    continue
                except Exception as e:
                    notes.append(f"pcolormesh: {e}")
            if isinstance(coll, PolyCollection) and not isinstance(coll, QuadMesh):
                try:                                    # fill_between
                    for p in coll.get_paths():
                        v = p.vertices
                        fc = coll.get_facecolor()
                        pf.add_trace(go.Scatter(
                            x=_tolist(v[:, 0]), y=_tolist(v[:, 1]),
                            fill="toself", mode="none",
                            fillcolor=_css(fc[0]) if len(fc) else "rgba(100,100,200,.3)",
                            hoverinfo="skip", showlegend=False))
                        added += 1
                except Exception as e:
                    notes.append(f"fill: {e}")
        pie = getattr(ax, "_cb_pie", None)             # captured pie
        if pie is not None:
            try:
                vals, labels = pie
                pf.add_trace(go.Pie(values=[float(v) for v in vals],
                                    labels=labels, hole=0))
                added += 1
            except Exception as e:
                notes.append(f"pie: {e}")
    return added


def convert(fig):
    """matplotlib Figure → (plotly Figure | None, notes)."""
    notes = []
    try:
        import plotly.graph_objects as go  # noqa: F401
    except Exception as e:
        return None, [f"plotly missing: {e}"]

    if any(getattr(ax, "name", "") == "3d" for ax in fig.axes):
        try:
            pf = _convert_3d(fig, notes)
        except Exception as e:
            notes.append(f"3d convert: {type(e).__name__}: {e}")
            pf = None
        return pf, notes[:_NOTES_LIMIT]

    pf = None
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        try:
            from plotly.tools import mpl_to_plotly
            pf = mpl_to_plotly(fig)
        except Exception as e:
            notes.append(f"mpl_to_plotly: {type(e).__name__}: {str(e)[:80]}")
    if pf is None:
        try:
            import plotly.graph_objects as go
            pf = go.Figure()
            t = fig.axes[0].get_title() if fig.axes else ""
            if t:
                pf.update_layout(title=t)
        except Exception as e:
            return None, notes + [f"empty fig: {e}"]

    try:
        _supplement_2d(fig, pf, notes)
    except Exception as e:
        notes.append(f"supplement: {type(e).__name__}: {e}")

    if not pf.data:
        return None, notes[:_NOTES_LIMIT] + ["no traces recovered"]

    try:
        pf.update_layout(template="plotly_white", autosize=True,
                         margin=dict(l=55, r=25, t=45, b=45))
    except Exception:
        pass
    return pf, notes[:_NOTES_LIMIT]
